using Dip.Application.Features.Intelligence;using Dip.Domain.Entities;using Microsoft.EntityFrameworkCore;
namespace Dip.Infrastructure.Persistence.Repositories;
public sealed class CommunityHardwareStore:Dip.Application.Features.Intelligence.ICommunityHardwareStore{readonly DipDbContext _db;public CommunityHardwareStore(DipDbContext db){_db=db;}public Task AddAsync(CommunityHardwareSample x,CancellationToken ct)=>_db.CommunityHardwareSamples.AddAsync(x,ct).AsTask();public async Task<IReadOnlyList<CommunityHardwareSample>> ListAsync(string key,CancellationToken ct)=>await _db.CommunityHardwareSamples.AsNoTracking().Where(x=>x.HardwareKey==key).OrderByDescending(x=>x.MeasuredAtUtc).Take(10000).ToListAsync(ct);}
public sealed class IntelligenceRunStore:IIntelligenceRunStore{readonly DipDbContext _db;public IntelligenceRunStore(DipDbContext db){_db=db;}public Task AddAsync(IntelligenceRun x,CancellationToken ct)=>_db.IntelligenceRuns.AddAsync(x,ct).AsTask();public Task<IntelligenceRun?> GetAsync(Guid id,CancellationToken ct)=>_db.IntelligenceRuns.SingleOrDefaultAsync(x=>x.Id==id,ct);public async Task<IReadOnlyList<IntelligenceRun>> ListRecentAsync(Guid p,int take,CancellationToken ct)=>await _db.IntelligenceRuns.AsNoTracking().Where(x=>x.ProjectId==p).OrderByDescending(x=>x.CreatedAtUtc).Take(Math.Clamp(take,1,200)).ToListAsync(ct);}
public sealed class ProjectForecastStore:IProjectForecastStore{readonly DipDbContext _db;public ProjectForecastStore(DipDbContext db){_db=db;}public Task AddAsync(ProjectForecast x,CancellationToken ct)=>_db.ProjectForecasts.AddAsync(x,ct).AsTask();public async Task<IReadOnlyList<ProjectForecast>> ListRecentAsync(Guid p,int take,CancellationToken ct)=>await _db.ProjectForecasts.AsNoTracking().Where(x=>x.ProjectId==p).OrderByDescending(x=>x.CreatedAtUtc).Take(Math.Clamp(take,1,200)).ToListAsync(ct);}
